INSERT OR IGNORE INTO blog_regions (id, name, sort_order) VALUES ('oriente-medio', 'Oriente Médio', 7);
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes)
VALUES ('2218a122-7647-432e-aed9-f7546e86a7b3', 'dubai-em-4-dias', 'draft', 'oriente-medio', 'Dubai em 4 dias: o show das fontes tem hora e quem chega depois das 23h perde', 'o show das fontes tem hora', 'Roteiro de Dubai em 4 dias com Downtown e as fontes, a Dubai antiga, o deserto e a Palm com a praia, os horários, o metrô do aeroporto, a entrada para brasileiros, valores em dirhams e em reais e o guia em PDF para baixar de graça.', 'O show das fontes é de graça, mas à noite só vai das 18h às 23h, a cada 30 minutos. O roteiro, os horários e o guia completo vão no celular.', 'Dubai', NULL, '/assets/blog/dubai-4-dias.jpg', '/assets/blog/dubai-4-dias-m.jpg', 'Silhueta dos arranha-céus de Dubai, com o Burj Khalifa ao centro, em um céu alaranjado de pôr do sol', 0, '[{"t":"pdf","href":"/guias/dubai-em-4-dias.pdf","note":"PDF de 16 páginas, feito para ler no celular. Grátis, sem cadastro."},{"t":"p","text":"Fontes, torre mais alta do mundo, Dubai antiga, deserto e praia, com os horários oficiais, o metrô do aeroporto e a entrada para brasileiros."},{"t":"tip","items":["Confira o passaporte e a entrada (seção Entrada).","Deixe a noite do Dia 1 livre para o show das fontes.","Reserve o deserto com antecedência e com operador licenciado."],"title":"Como usar este roteiro"},{"t":"whatsapp"},{"t":"afiliado"},{"t":"h","text":"Entrada para brasileiros","label":"Antes de viajar"},{"t":"tip","items":["O Brasil aparece como \"Visa Free\" na lista do Ministério das Relações Exteriores dos Emirados Árabes. A lista não informa o prazo de permanência: confirmar com a companhia aérea ou no site da ICP, o órgão de imigração dos Emirados, antes de comprar a passagem."],"title":"Brasileiro consta na lista de isenção de visto"},{"t":"ul","items":["**Passaporte:** O governo dos Emirados informa que o passaporte deve ter validade de pelo menos 6 meses a contar da data de entrada no país (seção atualizada em 13/07/2026).","**Uma divergência para conferir:** A página do aeroporto de Dubai com a lista de visto na chegada não cita o Brasil, e a lista de isenção do Ministério cita. As duas respondem a perguntas diferentes, mas por segurança confirmar com a companhia aérea antes de embarcar.","**Seguro viagem:** Não achamos exigência oficial de seguro para quem entra sem visto. É recomendação da Rota Certa contratar um, com cobertura médica: confirmar as regras do seu plano."]},{"t":"p","text":"Regras mudam: confirme em fontes oficiais antes de viajar (verificado em 12/11/2026)."},{"t":"h","text":"Do aeroporto ao centro","label":"Chegada e transporte"},{"t":"p","text":"O metrô da Linha Vermelha sai dos terminais 1 e 3 do aeroporto de Dubai (DXB) e para na estação Burj Khalifa/Dubai Mall."},{"t":"ul","items":["**Horários da Linha Vermelha no aeroporto:** Segunda a quinta e sábado: das 5h à meia-noite. Sexta: das 5h à 1h. **Domingo: só abre às 8h**, e fecha à meia-noite. Bilhetes nos guichês e máquinas dos terminais 1 e 3. Horários podem mudar em feriados.","**Cartão Nol e tarifas (RTA):** O cartão Nol tem versões Silver e Gold; a tarifa depende das zonas. Tabela da RTA em dirhams (AED), com R$ pelo BCB de 11/11/2026: A página da RTA não traz data nem o preço do cartão: confirmar. Veja as zonas do trajeto no planejador da RTA."]},{"t":"tip","items":["Não achamos tabela oficial de táxi do aeroporto ao centro: confirmar no aeroporto ou no hotel. O último show das fontes é às 23h e o metrô fecha à meia-noite."],"title":"Táxi e última viagem"},{"t":"h","text":"Downtown e as fontes","label":"Dia 1"},{"t":"p","text":"A torre mais alta do mundo, o Dubai Mall e o show das fontes, tudo na região de Downtown."},{"t":"img","src":"/assets/blog/dubai-fonte-barcos.jpg","alt":"Show noturno da fonte de Dubai com barcos tradicionais e arranha-céus ao fundo","caption":"Show noturno da fonte de Dubai.","credit":"Foto: Frederick Cana / Pexels","w":975,"h":650},{"t":"ul","items":["**Manhã · a partir das 8h30, Burj Khalifa e o mirante:** A torre tem 828 metros e 163 andares. O mirante At The Top abre todo dia, das 8h30 à meia-noite. Ingressos online ou no local. A página da Emaar não lista preços: confirmar no site oficial.","**Meio do dia, Dubai Mall:** Lojas: seg. a qui., das 10h às 23h; sex. a dom., das 10h à meia-noite. Restaurantes: seg. a qui., até meia-noite; sex. a dom., até 1h. Lá dentro fica o Dubai Aquarium & Underwater Zoo.","**Tarde e noite, Show das fontes:** Tarde: 13h e 13h30 (sáb. a qui.) ou 14h e 14h30 (sexta). Noite: das 18h às 23h, a cada 30 minutos. É de graça no calçadão: chegue 15 minutos antes."]},{"t":"tip","items":["**Noite, todo dia:** das 18h às 23h, a cada 30 minutos.","**Tarde, sábado a quinta:** 13h e 13h30. **Sexta:** 14h e 14h30.","Segundo a Emaar, o show é de graça para ver do calçadão. Horários podem mudar: confirmar no site oficial."],"title":"Show das fontes: todos os horários"},{"t":"tip","items":["Principal: Mirante da torre mais alta do mundo","Grátis: Show das fontes, visto do calçadão","Opcional: Aquário do Dubai Mall e passeio no lago (preço: confirmar)","**Na torre:** cerca de 2 horas","**No mall:** cerca de 3 horas","**Esforço:** leve, mas quente: faça pausas","Estimativas da Rota Certa, não dados oficiais.","**Dica da Rota Certa:** comece pela torre cedo e deixe o fim do dia livre para as fontes."],"title":"Para planejar o Dia 1"},{"t":"p","text":"[Abrir as fontes no Google Maps](https://www.google.com/maps/search/?api=1&query=Dubai%20Fountain%2C%20Downtown%20Dubai)"},{"t":"passeio","busca":"Dubai Burj Khalifa passeio Downtown","title":"Passeios em Downtown Dubai"},{"t":"h","text":"Dubai antiga","label":"Dia 2"},{"t":"p","text":"O bairro histórico de Al Fahidi, os souks e a travessia do Dubai Creek, o lado tradicional da cidade."},{"t":"img","src":"/assets/blog/dubai-creek-predios.jpg","alt":"Margem do Dubai Creek com prédios tradicionais e modernos e barcos","caption":"Margem do Dubai Creek.","credit":"Foto: Walid Ahmad / Pexels","w":1000,"h":666},{"t":"ul","items":["**Manhã, Al Fahidi Historical Neighbourhood:** Ruas estreitas de casas antigas, perto do Creek. Vá cedo: no calor do meio-dia a caminhada pesa. Horários de museus e galerias do bairro variam: confirmar.","**Meio do dia, Souks:** Os mercados tradicionais, como o de especiarias, ficam do outro lado do Creek. Cada loja tem o seu horário e o preço é combinado na hora: confirmar na loja.","**Fim da tarde, Travessia de abra no Creek:** O abra é o barco de madeira que cruza o canal entre as duas margens. Valor da passagem e horário: confirmar no local ou no site da RTA."]},{"t":"tip","items":["As páginas oficiais de Al Fahidi que abrimos não trazem horário nem preço. Fontes não oficiais dizem que o Museu de Dubai, no Forte Al Fahidi, está fechado para restauração em 2026: confirmar antes de ir."],"title":"Horários e preços: confirmar"},{"t":"tip","items":["Principal: Bairro histórico de Al Fahidi","Grátis: Caminhada pela beira do Creek e pelos souks","Opcional: Travessia de abra, o barco tradicional (preço: confirmar)","**Al Fahidi:** cerca de 2 horas","**Souks:** cerca de 2 horas","**Esforço:** moderado: calor e caminhada","Estimativas da Rota Certa, não dados oficiais.","**Como se vestir:** o guia oficial do Visit Dubai recomenda roupas mais discretas em áreas históricas e locais culturais.","**Dica da Rota Certa:** leve água, protetor solar e chapéu. O guia oficial do Visit Dubai recomenda proteger-se do sol, principalmente no verão."],"title":"Para planejar o Dia 2"},{"t":"p","text":"[Abrir Al Fahidi no Google Maps](https://www.google.com/maps/search/?api=1&query=Al%20Fahidi%20Historical%20Neighbourhood%2C%20Dubai)"},{"t":"passeio","busca":"Dubai antiga Al Fahidi passeio a pé","title":"Passeios na Dubai antiga"},{"t":"h","text":"Deserto","label":"Dia 3"},{"t":"p","text":"Um passeio pelas dunas, com saída da cidade no fim da tarde e volta à noite."},{"t":"img","src":"/assets/blog/dubai-deserto-por-do-sol.jpg","alt":"Dunas do deserto de Dubai com o sol se pondo","caption":"Dunas do deserto de Dubai.","credit":"Foto: Fabio Partenheimer / Pexels","w":1000,"h":666},{"t":"ul","items":["**Antes, Reserve com antecedência:** Feche o passeio com um operador que mostre licença e pergunte o que está incluído: transporte do hotel, jantar, bebidas e atividades. Guarde o comprovante no celular.","**Manhã, Descanso:** Depois de dois dias de caminhada, use a manhã para a piscina ou um café sem pressa. O passeio costuma pedir energia.","**Fim da tarde, Dunas e pôr do sol:** O passeio sai da cidade para o deserto. Leve água, protetor, óculos e um lenço para a poeira. Roupa leve, mas que cubra ombros e pernas, ajuda no sol.","**Noite, Volta ao hotel:** O operador costuma levar de volta. Combine o horário na reserva e confirme se o transporte está incluído."]},{"t":"tip","items":["Não achamos tabela oficial de preços. O Visit Dubai mantém um portal de experiências com passeios no deserto, listados por operador: confirmar valores, horários e o que está incluído antes de reservar."],"title":"Preço e operador: confirmar"},{"t":"tip","items":["Principal: Passeio pelas dunas, com operador licenciado","Grátis: Manhã livre na piscina ou no hotel","Opcional: Passeio de camelo ou jantar no deserto, se o operador oferecer","**No passeio:** cerca de 6 horas","**Manhã:** livre, para descansar","**Esforço:** leve, mas com sol e poeira","Estimativas da Rota Certa, não dados oficiais. Duração, saída e o que está incluído dependem do operador.","**Dica da Rota Certa:** deixe o dia seguinte mais leve. A Palm e a praia combinam com quem voltou tarde."],"title":"Para planejar o Dia 3"},{"t":"p","text":"[Portal de experiências do Visit Dubai](https://experiences.visitdubai.com/category/2628)"},{"t":"passeio","busca":"Dubai safári no deserto","title":"Passeios ao deserto de Dubai"},{"t":"h","text":"Palm e praia","label":"Dia 4"},{"t":"p","text":"A Palm Jumeirah de manhã e uma praia de Jumeirah à tarde, com o Burj Al Arab ao fundo."},{"t":"img","src":"/assets/blog/dubai-palm-praia.jpg","alt":"Praia de areia clara na Palm Jumeirah, com palmeiras e o skyline de Dubai ao fundo","caption":"Praia de areia clara na Palm Jumeirah.","credit":"Foto: Ayrat / Pexels","w":1000,"h":666},{"t":"ul","items":["**Manhã, Palm Jumeirah:** A ilha artificial em forma de palmeira, com praias, hotéis e vista para o skyline. Como chegar e preços de mirantes: confirmar. Não achamos fonte oficial com valores.","**Tarde, Praia de Jumeirah:** Descanse na areia com o Burj Al Arab ao fundo. Maiô e sunga são adequados na praia e na piscina, mas não em shoppings e áreas comerciais, conforme o guia do Visit Dubai.","**Opcional · dia inteiro, Abu Dhabi: Grande Mesquita:** Sáb. a qui., das 9h às 20h30; sexta, das 9h às 11h30 e das 14h30 às 20h30. O site pede reserva online do passe de acesso. Entrada, vestimenta e transporte desde Dubai: confirmar."]},{"t":"tip","items":["O guia oficial do Visit Dubai (edição de 2024) diz que a cidade tem parques e praias gratuitos. O que cobra à parte, como cadeiras e guarda-sóis, e os horários de cada praia: confirmar no local."],"title":"Praias gratuitas, com ressalva"},{"t":"tip","items":["Principal: Palm Jumeirah","Grátis: Praias públicas de Jumeirah","Opcional: Bate-volta a Abu Dhabi, à Grande Mesquita Sheikh Zayed","**Palm:** cerca de 2 horas","**Praia:** cerca de 3 horas","**Esforço:** leve: dia de despedida","Estimativas da Rota Certa, não dados oficiais.","**Dica da Rota Certa:** se for a Abu Dhabi, troque a manhã da Palm por esse dia e confira o horário do voo de volta."],"title":"Para planejar o Dia 4"},{"t":"p","text":"[Abrir a Palm Jumeirah no Google Maps](https://www.google.com/maps/search/?api=1&query=Palm%20Jumeirah%2C%20Dubai)"},{"t":"passeio","busca":"Dubai Palm Jumeirah passeio","title":"Passeios na Palm Jumeirah"},{"t":"h","text":"Dinheiro, tomada e regras locais","label":"Na prática"},{"t":"ul","items":["**Dirham (AED):** A moeda é o dirham dos Emirados (AED). Referência do Banco Central de 11/11/2026: AED 10 valem cerca de R$ 15,14. Para converter de cabeça, multiplique o preço em dirhams por 1,5. O BCB lista 1 dólar = 3,6725 AED.","**Tomada e voltagem:** Não abrimos uma fonte oficial sobre o padrão de tomada dos Emirados: confirmar antes de viajar. Leve um adaptador universal e confira se o seu aparelho é bivolt."]},{"t":"tip","items":["Segundo o guia oficial do Visit Dubai (edição de 2024): todas as roupas são em geral aceitas, mas é aconselhável se vestir de forma mais discreta em áreas históricas e locais culturais. Roupa de banho é adequada na praia e na piscina, não em shoppings e áreas comerciais.","Adultos não muçulmanos com 21 anos ou mais podem consumir álcool em hotéis, bares e restaurantes licenciados. Dar as mãos é permitido, mas o guia pede que se evitem demonstrações exageradas de afeto em público."],"title":"Regras locais, em resumo"},{"t":"p","text":"O site oficial do Museu do Futuro informa, em 12/11/2026, fechamento temporário: por isso ele não está no roteiro. Regras mudam: confirme nos sites oficiais do governo e do turismo de Dubai antes de viajar."},{"t":"h","text":"Orçamento e checklist","label":"Planejamento"},{"t":"p","text":"O preço da passagem não é o preço da viagem."},{"t":"p","text":"Ingressos e passeios não têm fonte oficial aberta por nós, então o guia não soma nada. Só o metrô tem tarifa oficial. Reais pelo Banco Central, 11/11/2026 (AED 1 = R$ 1,5141)."},{"t":"tip","items":["Passaporte com 6 meses ou mais de validade e prazo de permanência confirmado.","Reservar o passeio do deserto com operador licenciado.","Conferir horários das fontes, da torre e do último metrô.","Levar protetor solar, água e roupa leve que cubra ombros e pernas."],"title":"Checklist da viagem"},{"t":"pdf","href":"/guias/dubai-em-4-dias.pdf","note":"Leve o roteiro, as rotas e o orçamento no celular. Grátis, sem cadastro."},{"t":"h","text":"Valores e fontes","label":"Transparência"},{"t":"p","text":"Conferido em 12/11/2026. Reais pela cotação de venda do Banco Central de 11/11/2026: AED 1 = R$ 1,5141. Itens marcados \"confirmar\" não têm fonte oficial atual ou a página não abriu."},{"t":"tip","items":["Fontes e show: [Emaar, Dubai Fountain](https://www.emaar.com/en/dubai-fountain)","Torre e mirante: [Emaar, Burj Khalifa](https://www.emaar.com/en/other-emaar-businesses/burj-khalifa). Mall: [Emaar, Dubai Mall](https://www.emaar.com/en/dubai-mall) e [horários do Dubai Mall](https://thedubaimall.com/en/plan-your-visit/opening-hours)","Metrô no aeroporto: [Dubai Airports](https://dubaiairports.ae/transport/metro). Tarifas: [RTA, Nol Fares](https://rta.ae/wps/portal/rta/ae/public-transport/Nol-Fares) (sem data na página)","Isenção de visto: [Ministério das Relações Exteriores dos EAU](https://www.mofa.gov.ae/en/visa-exemptions-for-non-citizen) (sem prazo na página). Validade do passaporte: [Portal do governo dos EAU](https://u.ae/en/information-and-services/visa-and-emirates-id/Visa-information/do-you-need-an-entry-permit-or-a-visa-to-enter-the-uae), atualizado em 13/07/2026","Lista de visto na chegada: [Dubai Airports](https://dubaiairports.ae/information/immigration-visas) (não cita o Brasil)","Regras locais e praias: [guia oficial do Visit Dubai, 2024](https://www.visitdubai.com/en/-/media/Files/guides/dubai-mini-guide-04-cultural-explorer.pdf). Experiências: [portal do Visit Dubai](https://experiences.visitdubai.com/category/2628)","Mesquita: [Sheikh Zayed Grand Mosque Center](https://www.szgmc.gov.ae/en). Museu do Futuro: [site oficial](https://www.museumofthefuture.ae/en)","Câmbio: [Banco Central, fechamento de 11/11/2026](https://www4.bcb.gov.br/Download/fechamento/20261111.csv)"],"title":"Fontes oficiais, conferidas em 12/11/2026"},{"t":"p","text":"Não confirmados: prazo de permanência sem visto, preços de ingressos, deserto, Palm, abra e táxi, horários de Al Fahidi e dos souks, tomada, regras de vestimenta da mesquita e transporte a Abu Dhabi. As estimativas de tempo e as dicas são da Rota Certa. Guia independente, sem vínculo com as marcas e empresas citadas."},{"t":"tip","items":["Prazo de permanência sem visto para brasileiros (a lista do Ministério não traz; guia manda confirmar com a companhia aérea ou a ICP)","Divergência: a página de visto na chegada do aeroporto de Dubai não cita o Brasil; a lista de isenção do Ministério cita","Preços do mirante, do aquário, da passarela e do passeio no lago, do deserto, da Palm, do abra e dos souks","Preço do cartão Nol e zonas do trajeto aeroporto até Downtown","Tabela de táxi do aeroporto ao centro","Horários de Al Fahidi, dos souks e do abra; estado do Museu de Dubai (só fonte não oficial)","Tomada e voltagem dos EAU (fonte oficial não aberta)","Regras de vestimenta da Grande Mesquita e transporte de Dubai a Abu Dhabi","Operadores licenciados de safári (sem lista oficial de licenças aberta)","Se a edição de 2024 do guia do Visit Dubai (vestimenta, álcool, afeto em público, praias gratuitas) continua vigente"],"title":"O que este guia não informa"},{"t":"p","text":"Preços, horários e regras mudam: confira nas fontes acima antes de ir. As estimativas de tempo e esforço e as dicas marcadas como da Rota Certa são recomendações nossas, não dados oficiais."},{"t":"p","text":"Foto de capa: Saeed Alsoomehi / Pexels."},{"t":"whatsapp"},{"t":"p","text":"Quer montar o roteiro da viagem inteira? Use o [Planner grátis da Rota Certa](https://rotacertapassagens.com/#/planner)."},{"t":"contato"},{"t":"afiliado"}]', 11);
